-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- signal-photos-live-buttons
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal photos + all partners (buttons)',
  '📸 The Signal photos are here',
  '320 photos from the afternoon, ready to browse and download.',
  'subscribers',
  $nl$[{"id":"signal-photos-live-buttons-01","type":"header","text":"The Signal photos are here.","size":"lg"},{"id":"signal-photos-live-buttons-02","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-photos-collage.jpg","alt":"A collage of photos from Signal: the TEDxNewy stage, a guest celebrating, an applauding audience and two friends on the balcony","widthPct":"full","href":"https://tedxnewy.com.au/signal"},{"id":"signal-photos-live-buttons-03","type":"text","html":"<p>320 photos from Signal are now live on our website, captured on the day by our media partner Newy Digital.</p><p>Find yourself, your friends or your favourite moment from the afternoon, then browse and download the full set.</p>"},{"id":"signal-photos-live-buttons-04","type":"button","label":"See the Signal photos","href":"https://tedxnewy.com.au/signal","align":"center","theme":"red","variant":"solid"},{"id":"signal-photos-live-buttons-05","type":"text","html":"<p>The talks are next. We'll add each video to the same page as it goes live, so keep an eye on it.</p>"},{"id":"signal-photos-live-buttons-06","type":"divider","style":"short","colour":"soft"},{"id":"signal-photos-live-buttons-07","type":"header","text":"Thank you to our activating partners","size":"md"},{"id":"signal-photos-live-buttons-08","type":"text","html":"<p>Activation Alley was a big part of what made Signal feel alive, and that was down to these partners. Thank you for giving your time, your ideas and your energy to the day.</p>"},{"id":"signal-photos-live-buttons-11","type":"header","text":"Henderson","size":"md"},{"id":"signal-photos-live-buttons-12","type":"columns","cols":[[{"id":"signal-photos-live-buttons-09","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-henderson.jpg","alt":"Henderson merchandise on the Henderson stall at Signal","widthPct":100}],[{"id":"signal-photos-live-buttons-10","kind":"button","label":"Learn more about Henderson","href":"https://henderson.com.au","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-15","type":"header","text":"Sketch It Live","size":"md"},{"id":"signal-photos-live-buttons-16","type":"columns","cols":[[{"id":"signal-photos-live-buttons-14","kind":"button","label":"Learn more about Sketch It Live","href":"http://sketchitlive.com.au","align":"left","theme":"red","variant":"solid"}],[{"id":"signal-photos-live-buttons-13","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-sketch-it-live.jpg","alt":"A Sketch It Live graphic recording of Signal on a desk","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-19","type":"header","text":"Ink and Snow","size":"md"},{"id":"signal-photos-live-buttons-20","type":"columns","cols":[[{"id":"signal-photos-live-buttons-17","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-ink-and-snow.jpg","alt":"An Ink and Snow artist painting a live watercolour portrait","widthPct":100}],[{"id":"signal-photos-live-buttons-18","kind":"button","label":"Learn more about Ink and Snow","href":"https://www.inkandsnow.com","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-23","type":"header","text":"Talk2MeBro","size":"md"},{"id":"signal-photos-live-buttons-24","type":"columns","cols":[[{"id":"signal-photos-live-buttons-22","kind":"button","label":"Learn more about Talk2MeBro","href":"https://www.talk2mebro.org.au","align":"left","theme":"red","variant":"solid"}],[{"id":"signal-photos-live-buttons-21","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-talk2mebro.jpg","alt":"Talk2MeBro merchandise on the Talk2MeBro stand","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-27","type":"header","text":"New Artists Collective","size":"md"},{"id":"signal-photos-live-buttons-28","type":"columns","cols":[[{"id":"signal-photos-live-buttons-25","kind":"image","src":"","alt":"New Artists Collective at Signal","widthPct":100}],[{"id":"signal-photos-live-buttons-26","kind":"button","label":"Learn more about New Artists Collective","href":"https://www.newartistscollective.com","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-31","type":"header","text":"Akrue","size":"md"},{"id":"signal-photos-live-buttons-32","type":"columns","cols":[[{"id":"signal-photos-live-buttons-30","kind":"button","label":"Learn more about Akrue","href":"https://akrue.com.au","align":"left","theme":"red","variant":"solid"}],[{"id":"signal-photos-live-buttons-29","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-akrue.jpg","alt":"Akrue flyers and stickers on the Akrue stall","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-35","type":"header","text":"InHouse Plants","size":"md"},{"id":"signal-photos-live-buttons-36","type":"columns","cols":[[{"id":"signal-photos-live-buttons-33","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-inhouse-plants.jpg","alt":"Guests potting plants at the InHouse Plants activation","widthPct":100}],[{"id":"signal-photos-live-buttons-34","kind":"button","label":"Learn more about InHouse Plants","href":"https://www.inhouseplants.com.au","align":"left","theme":"red","variant":"solid"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-39","type":"header","text":"The Bridge Project","size":"md"},{"id":"signal-photos-live-buttons-40","type":"columns","cols":[[{"id":"signal-photos-live-buttons-38","kind":"button","label":"Learn more about The Bridge Project","href":"https://www.thebridgeproject.com.au","align"