ft","theme":"red","variant":"solid"}],[{"id":"signal-photos-live-buttons-53","kind":"image","src":"","alt":"Meandrix at Signal","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-buttons-57","type":"divider","style":"short","colour":"soft"},{"id":"signal-photos-live-buttons-58","type":"text","html":"<p>Thank you for being part of Signal.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
